mapper.select:
SELECT r.*, d.name AS device_name, d.device_no, u.real_name AS inspector_name
FROM inspection_record r
LEFT JOIN device d ON r.device_id = d.id
LEFT JOIN user u ON r.inspector_id = u.id

    AND r.device_id = #{deviceId}
    AND r.result = #{result}

ORDER BY r.inspect_time DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM inspection_record

    AND device_id = #{deviceId}
    AND result = #{result}
